'use strict';

// Immutable P2 input snapshot. It is intentionally separate from the public
// source tree so a candidate build cannot depend on a runtime public-file read.
const zlib = require('node:zlib');
const PAGES = Object.freeze({
  "index.html": "",
  "tools/blog/index.html": "",
});

function readFrozenPage(route) {
  const value = PAGES[route];
  if (!value) throw new Error(`No frozen candidate source for ${route}`);
  return zlib.gunzipSync(Buffer.from(value, 'base64')).toString('utf8');
}

module.exports = { readFrozenPage };
